// ============================================================================
// RETO 1: JERARQUÍA DE CLASES CON HERENCIA Y POLIMORFISMO
// ============================================================================

// 1. Clase Base
class ProductoBase {
  constructor({ id, sku, nombre, categoria, proveedor, precioCostoUSD, margenGanancia, precioVentaCRC, stock, ajusteAutomatico, protegidoPorContrato }) {
    this.id = id;
    this.sku = sku;
    this.nombre = nombre;
    this.categoria = categoria || 'General';
    this.proveedor = proveedor || 'No asignado';
    this.precioCostoUSD = Number(precioCostoUSD);
    this.margenGanancia = Number(margenGanancia);
    this.precioVentaCRC = Number(precioVentaCRC);
    this.stock = Number(stock || 0);
    this.ajusteAutomatico = Boolean(ajusteAutomatico);
    this.protegidoPorContrato = Boolean(protegidoPorContrato);
  }

  esElegibleParaAjuste() {
    if (!this.ajusteAutomatico) return { elegible: false, razon: 'Ajuste desactivado' };
    if (this.protegidoPorContrato) return { elegible: false, razon: 'Protegido por contrato' };
    if (this.stock <= 0) return { elegible: false, razon: 'Sin stock' };
    return { elegible: true, razon: 'Apto para recálculo' };
  }

  // Método base a sobreescribir (Polimorfismo)
  calcularNuevoPrecioCRC(nuevoTipoCambio) {
    const validacion = this.esElegibleParaAjuste();
    if (!validacion.elegible) {
      return { precioActualizado: false, precioFinalCRC: this.precioVentaCRC, razon: validacion.razon, tipoRegla: 'Base' };
    }
    const baseUSD = this.precioCostoUSD * (1 + this.margenGanancia);
    const nuevoPrecioCRC = Math.round(baseUSD * nuevoTipoCambio);
    return {
      precioActualizado: true,
      precioAnteriorCRC: this.precioVentaCRC,
      nuevoPrecioCRC,
      diferenciaCRC: nuevoPrecioCRC - this.precioVentaCRC,
      razon: validacion.razon,
      tipoRegla: 'Base Genérica'
    };
  }
}

// 2. Subclase 1: Bienes Físicos / Hardware (Hereda de ProductoBase)
class ProductoHardware extends ProductoBase {
  constructor(data) {
    super(data);
    this.recargoLogisticaUSD = 0.03; // 3% recargo logístico de flete y aduana
  }

  // Sobreescritura polimórfica: Aplica aranceles y transporte físico
  calcularNuevoPrecioCRC(nuevoTipoCambio) {
    const validacion = this.esElegibleParaAjuste();
    if (!validacion.elegible) {
      return { precioActualizado: false, precioFinalCRC: this.precioVentaCRC, razon: validacion.razon, tipoRegla: 'Hardware Físico' };
    }

    const costoTotalUSD = this.precioCostoUSD * (1 + this.recargoLogisticaUSD);
    const baseConMargenUSD = costoTotalUSD * (1 + this.margenGanancia);
    const nuevoPrecioCRC = Math.round(baseConMargenUSD * nuevoTipoCambio);

    return {
      precioActualizado: true,
      precioAnteriorCRC: this.precioVentaCRC,
      nuevoPrecioCRC,
      diferenciaCRC: nuevoPrecioCRC - this.precioVentaCRC,
      razon: `${validacion.razon} (Aplica recargo logístico hardware)`,
      tipoRegla: 'Hardware Físico'
    };
  }
}

// 3. Subclase 2: Software y Licencias Digitales (Hereda de ProductoBase)
class ProductoLicenciaDigital extends ProductoBase {
  constructor(data) {
    super(data);
    this.impuestoServicioDigital = 0.02; // 2% retención transfronteriza digital
  }

  // Sobreescritura polimórfica: Aplica tributo de intangibles sin flete
  calcularNuevoPrecioCRC(nuevoTipoCambio) {
    const validacion = this.esElegibleParaAjuste();
    if (!validacion.elegible) {
      return { precioActualizado: false, precioFinalCRC: this.precioVentaCRC, razon: validacion.razon, tipoRegla: 'Licencia Digital' };
    }

    const baseUSD = this.precioCostoUSD * (1 + this.margenGanancia + this.impuestoServicioDigital);
    const nuevoPrecioCRC = Math.round(baseUSD * nuevoTipoCambio);

    return {
      precioActualizado: true,
      precioAnteriorCRC: this.precioVentaCRC,
      nuevoPrecioCRC,
      diferenciaCRC: nuevoPrecioCRC - this.precioVentaCRC,
      razon: `${validacion.razon} (Aplica factor fiscal digital)`,
      tipoRegla: 'Licencia Digital'
    };
  }
}

// 4. Entidad Monitor de Divisa
class MonitorDivisa {
  constructor(tipoCambioActual, tipoCambioHistorico) {
    if (typeof tipoCambioActual !== 'number' || isNaN(tipoCambioActual) || tipoCambioActual <= 0) {
      throw new Error(`[MonitorDivisa] Tipo de cambio actual inválido: ${tipoCambioActual}`);
    }
    if (typeof tipoCambioHistorico !== 'number' || isNaN(tipoCambioHistorico) || tipoCambioHistorico <= 0) {
      throw new Error(`[MonitorDivisa] Tipo de cambio histórico inválido: ${tipoCambioHistorico}`);
    }
    this.tipoCambioActual = tipoCambioActual;
    this.tipoCambioHistorico = tipoCambioHistorico;
  }

  calcularVariacionPorcentual() {
    const variacion = ((this.tipoCambioActual - this.tipoCambioHistorico) / this.tipoCambioHistorico) * 100;
    return Number(variacion.toFixed(4));
  }

  obtenerDiagnostico(umbralAlerta, umbralCritico) {
    const variacion = this.calcularVariacionPorcentual();
    let tendencia = 'ESTABLE';
    if (variacion > 0) tendencia = 'ALCISTA';
    else if (variacion < 0) tendencia = 'BAJISTA';

    const esCritico = Math.abs(variacion) >= umbralCritico;
    const esAlerta = Math.abs(variacion) >= umbralAlerta;

    return {
      variacionPorcentual: variacion,
      tendencia,
      nivelRiesgo: esCritico ? 'CRITICO' : (esAlerta ? 'MODERADO' : 'BAJO'),
      requiereAjuste: esCritico
    };
  }
}

// ============================================================================
// EXTRACCIÓN Y EJECUCIÓN EN N8N
// ============================================================================

// 1. Tipo de Cambio (Soporta API de Hacienda o mock local)
const rawTC = $('HTTP_API_TipoCambio').first().json;
let tcActual = null;
if (rawTC.dolar?.venta?.valor) {
  tcActual = Number(rawTC.dolar.venta.valor);
} else if (rawTC.venta?.valor) {
  tcActual = Number(rawTC.venta.valor);
} else if (rawTC.tipoCambioVenta || rawTC.valor) {
  tcActual = Number(rawTC.tipoCambioVenta || rawTC.valor);
} else {
  tcActual = Number(rawTC.precio || rawTC.rate || Object.values(rawTC)[0]);
}

// 2. Feriados Oficiales (Segunda API / Reto 2)
const feriadosRaw = $('HTTP_API_FeriadosCR').all().map(item => item.json);
const fechaHoy = new Date();
const fechaHoyISO = fechaHoy.toISOString().split('T')[0];
const esFinDeSemana = (fechaHoy.getDay() === 0 || fechaHoy.getDay() === 6);
const feriadoHoy = feriadosRaw.find(f => f.date === fechaHoyISO);
const esDiaFeriado = Boolean(feriadoHoy);

// Regla de Negocio Reto 2: El mercado cambiario solo opera en días hábiles
const mercadoAbierto = !esDiaFeriado && !esFinDeSemana;

// 3. Histórico de JSON Server
const historicoLista = $('HTTP_JSON_Server_Historico').all().map(item => item.json);
const ultimoRegistro = historicoLista[historicoLista.length - 1];
const ultimoHistorico = Number(ultimoRegistro.tipoCambioVenta || ultimoRegistro.valor);

// 4. Catálogo de Productos y Desduplicación
const todosProductosRaw = $('HTTP_JSON_Server_Productos').all().map(item => item.json);
const mapaProductos = new Map();
todosProductosRaw.forEach(p => {
  if (p && p.id && !mapaProductos.has(p.id)) {
    mapaProductos.set(p.id, p);
  }
});
const catalogoUnico = Array.from(mapaProductos.values());

// 5. Instanciación y Diagnóstico
const UMBRAL_ALERTA = 1.0;
const UMBRAL_CRITICO = 1.5;

const monitor = new MonitorDivisa(tcActual, ultimoHistorico);
const diagnostico = monitor.obtenerDiagnostico(UMBRAL_ALERTA, UMBRAL_CRITICO);

// Decisión Final Combinada (Reto 2): Solo se ajusta si hay volatilidad Y el mercado está abierto
const requiereAjusteFinal = diagnostico.requiereAjuste && mercadoAbierto;

const productosAjustados = [];
const productosOmitidos = [];

// 6. Aplicación Polimórfica según la Categoría (Reto 1)
catalogoUnico.forEach(item => {
  let productoInstanciado;
  const cat = (item.categoria || '').toLowerCase();

  if (cat.includes('licencia') || cat.includes('software') || cat.includes('digital') || cat.includes('servicio')) {
    productoInstanciado = new ProductoLicenciaDigital(item);
  } else {
    productoInstanciado = new ProductoHardware(item);
  }

  // Método común ejecutado de forma polimórfica
  const resultado = productoInstanciado.calcularNuevoPrecioCRC(monitor.tipoCambioActual);

  if (resultado.precioActualizado) {
    productosAjustados.push({
      id: String(productoInstanciado.id),
      sku: String(productoInstanciado.sku),
      nombre: String(productoInstanciado.nombre),
      categoria: String(productoInstanciado.categoria),
      reglaAplicada: resultado.tipoRegla,
      precioAnteriorCRC: Number(resultado.precioAnteriorCRC),
      nuevoPrecioVentaCRC: Number(resultado.nuevoPrecioCRC),
      diferenciaCRC: Number(resultado.diferenciaCRC),
      motivo: String(resultado.razon)
    });
  } else {
    productosOmitidos.push({
      id: String(productoInstanciado.id),
      sku: String(productoInstanciado.sku),
      nombre: String(productoInstanciado.nombre),
      reglaAplicada: resultado.tipoRegla,
      precioFinalCRC: Number(resultado.precioFinalCRC),
      motivo: String(resultado.razon)
    });
  }
});

// 7. Salida consolidada
return [
  {
    json: {
      tipoCambioActual: monitor.tipoCambioActual,
      tipoCambioHistorico: monitor.tipoCambioHistorico,
      variacionPorcentual: diagnostico.variacionPorcentual,
      tendencia: diagnostico.tendencia,
      nivelRiesgo: diagnostico.nivelRiesgo,
      mercadoAbierto,
      requiereAjuste: requiereAjusteFinal,
      motivoMercado: !mercadoAbierto 
        ? (esFinDeSemana ? 'Mercado cerrado por fin de semana' : `Mercado cerrado por feriado bancario: ${feriadoHoy.localName}`)
        : 'Mercado financiero abierto',
      calendarioMercado: {
        esDiaFeriado,
        nombreFeriado: feriadoHoy ? feriadoHoy.localName : 'Día hábil regular',
        esFinDeSemana
      },
      totalEvaluados: catalogoUnico.length,
      totalAjustados: productosAjustados.length,
      totalOmitidos: productosOmitidos.length,
      productosAjustados,
      productosOmitidos
    }
  }
];

