// 1. Extraemos los datos calculados por el nodo POO
const datosPOO = $('Code_POO_LogicaNegocio').first().json;

// 2. Extraemos el dictamen generado por el Agente de IA
const dictamenIA = $('Agente_Auditor_Precios').first().json.output;

// 3. Estructuramos la comparativa de productos (Antes vs Después)
const detalleProductosAjustados = datosPOO.productosAjustados.map(prod => ({
  producto: prod.nombre,
  categoria: prod.categoria,
  precioOriginalCRC: `₡${prod.precioAnteriorCRC.toLocaleString('es-CR')}`,
  nuevoPrecioCRC: `₡${prod.nuevoPrecioVentaCRC.toLocaleString('es-CR')}`,
  diferenciaAjuste: `₡${prod.diferenciaCRC.toLocaleString('es-CR')}`,
  estado: 'Actualizado en DB'
}));

const productosOmitidos = datosPOO.productosOmitidos.map(prod => ({
  producto: prod.nombre,
  precioActualCRC: `₡${prod.precioFinalCRC.toLocaleString('es-CR')}`,
  motivoExclusion: prod.motivo
}));

// 4. Retornamos el objeto consolidado para mostrar en pantalla
return [{
  json: {
    estadoOperacion: "Ajuste de Precios Ejecutado Exitosamente",
    fechaEjecucion: new Date().toLocaleString('es-CR'),
    resumenMercado: {
      tipoCambioHistorico: `₡${datosPOO.tipoCambioHistorico}`,
      tipoCambioActual: `₡${datosPOO.tipoCambioActual}`,
      variacionPorcentual: `${datosPOO.variacionPorcentual}%`,
      tendencia: datosPOO.tendencia,
      nivelRiesgo: datosPOO.nivelRiesgo
    },
    resumenInventario: {
      totalEvaluados: datosPOO.totalEvaluados,
      totalActualizados: datosPOO.totalAjustados,
      totalSinCambios: datosPOO.totalOmitidos
    },
    comparativaPrecios: detalleProductosAjustados,
    productosNoModificados: productosOmitidos,
    auditoriaInteligenciaArtificial: dictamenIA
  }
}];
